struct berval **encode_kerberos_key(const krb5_key_data *key_data_in, int n_key_data, krb5_kvno mkvno) {
    struct berval **encoded_keys = NULL;
    krb5_key_data *key_data = NULL;
    int i, j, unique_kvno_count = 0;

    if (n_key_data <= 0 || !key_data_in) {
        return NULL;
    }

    key_data = malloc(n_key_data * sizeof(krb5_key_data));
    if (!key_data) {
        return NULL;
    }

    for (i = 0; i < n_key_data; i++) {
        key_data[i] = key_data_in[i];
    }

    for (i = 0; i < n_key_data; i++) {
        if (key_data[i].key_data_ver == 0) {
            key_data[i].key_data_ver = mkvno;
        }
    }

    for (i = 0; i < n_key_data; i++) {
        int is_unique = 1;
        for (j = 0; j < unique_kvno_count; j++) {
            if (key_data[i].key_data_ver == key_data[j].key_data_ver) {
                is_unique = 0;
                break;
            }
        }
        if (is_unique) {
            unique_kvno_count++;
        }
    }

    encoded_keys = calloc(unique_kvno_count, sizeof(struct berval *));
    if (!encoded_keys) {
        free(key_data);
        return NULL;
    }

    int encoded_index = 0;
    for (i = 0; i < n_key_data; i++) {
        int is_unique = 1;
        for (j = 0; j < encoded_index; j++) {
            if (key_data[i].key_data_ver == key_data[j].key_data_ver) {
                is_unique = 0;
                break;
            }
        }
        if (is_unique) {
            encoded_keys[encoded_index] = malloc(sizeof(struct berval));
            if (!encoded_keys[encoded_index]) {
                for (int k = 0; k < encoded_index; k++) {
                    free(encoded_keys[k]);
                }
                free(encoded_keys);
                free(key_data);
                return NULL;
            }

            encoded_keys[encoded_index]->bv_len = key_data[i].key_data_length;
            encoded_keys[encoded_index]->bv_val = malloc(key_data[i].key_data_length);
            if (!encoded_keys[encoded_index]->bv_val) {
                free(encoded_keys[encoded_index]);
                for (int k = 0; k < encoded_index; k++) {
                    free(encoded_keys[k]);
                }
                free(encoded_keys);
                free(key_data);
                return NULL;
            }

            memcpy(encoded_keys[encoded_index]->bv_val, key_data[i].key_data, key_data[i].key_data_length);
            encoded_index++;
        }
    }

    free(key_data);
    return encoded_keys;
}

struct berval** encode_krb5_keys(krb5_key_data* key_data_in, int n_key_data, krb5_kvno mkvno) {
    if (n_key_data <= 0 || key_data_in == NULL) {
        return NULL;
    }

    struct berval** encoded_keys = NULL;
    krb5_key_data* key_data_copy = NULL;
    int unique_kvno_count = 0;
    krb5_kvno* unique_kvno_list = NULL;

    // Make a shallow copy of the key data
    key_data_copy = malloc(n_key_data * sizeof(krb5_key_data));
    if (key_data_copy == NULL) {
        return NULL;
    }

    for (int i = 0; i < n_key_data; i++) {
        key_data_copy[i] = key_data_in[i];
    }

    // Count the number of unique key versions
    for (int i = 0; i < n_key_data; i++) {
        int is_unique = 1;
        for (int j = 0; j < unique_kvno_count; j++) {
            if (unique_kvno_list[j] == key_data_copy[i].key_data_ver) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            unique_kvno_count++;
            unique_kvno_list = realloc(unique_kvno_list, unique_kvno_count * sizeof(krb5_kvno));
            if (unique_kvno_list == NULL) {
                free(key_data_copy);
                return NULL;
            }
            unique_kvno_list[unique_kvno_count - 1] = key_data_copy[i].key_data_ver;
        }
    }

    // Allocate memory for the result
    encoded_keys = calloc(unique_kvno_count, sizeof(struct berval*));
    if (encoded_keys == NULL) {
        free(key_data_copy);
        free(unique_kvno_list);
        return NULL;
    }

    for (int i = 0; i < unique_kvno_count; i++) {
        krb5_kvno current_kvno = unique_kvno_list[i];
        int key_count = 0;

        // Count the number of keys with the current version
        for (int j = 0; j < n_key_data; j++) {
            if (key_data_copy[j].key_data_ver == current_kvno) {
                key_count++;
            }
        }

        // Allocate and encode keys for the current version
        encoded_keys[i] = calloc(key_count, sizeof(struct berval));
        if (encoded_keys[i] == NULL) {
            for (int k = 0; k < i; k++) {
                free(encoded_keys[k]);
            }
            free(encoded_keys);
            free(key_data_copy);
            free(unique_kvno_list);
            return NULL;
        }

        int index = 0;
        for (int j = 0; j < n_key_data; j++) {
            if (key_data_copy[j].key_data_ver == current_kvno) {
                encoded_keys[i][index].bv_len = key_data_copy[j].key_data_length;
                encoded_keys[i][index].bv_val = malloc(encoded_keys[i][index].bv_len);
                if (encoded_keys[i][index].bv_val == NULL) {
                    // Clean up already allocated memory
                    for (int k = 0; k < index; k++) {
                        free(encoded_keys[i][k].bv_val);
                    }
                    free(encoded_keys[i]);
                    for (int k = 0; k < i; k++) {
                        free(encoded_keys[k]);
                    }
                    free(encoded_keys);
                    free(key_data_copy);
                    free(unique_kvno_list);
                    return NULL;
                }
                memcpy(encoded_keys[i][index].bv_val, key_data_copy[j].key_data, encoded_keys[i][index].bv_len);
                index++;
            }
        }
    }

    // Free memory
    free(key_data_copy);
    free(unique_kvno_list);

    return encoded_keys;
}

