struct berval **krb5_encode_keys(krb5_key_data *key_data_in, int n_key_data, krb5_kvno mkvno) {
    struct berval **encoded_keys = NULL;
    krb5_key_data *key_data = NULL;
    int i, j, unique_kvno_count = 0;
    krb5_error_code ret = 0;

    if (n_key_data <= 0) {
        return NULL;
    }

    key_data = malloc(n_key_data * sizeof(krb5_key_data));
    if (!key_data) {
        return NULL;
    }

    memcpy(key_data, key_data_in, n_key_data * sizeof(krb5_key_data));

    for (i = 0; i < n_key_data; i++) {
        if (key_data[i].keyblock.enctype == ENCTYPE_NULL) {
            key_data[i].key_data_ver = mkvno;
        }
    }

    for (i = 0; i < n_key_data; i++) {
        int is_unique = 1;
        for (j = 0; j < unique_kvno_count; j++) {
            if (encoded_keys[j] && encoded_keys[j]->bv_val && 
                memcmp(encoded_keys[j]->bv_val, &key_data[i], sizeof(krb5_key_data)) == 0) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            encoded_keys = realloc(encoded_keys, (unique_kvno_count + 1) * sizeof(struct berval *));
            if (!encoded_keys) {
                ret = ENOMEM;
                goto cleanup;
            }

            encoded_keys[unique_kvno_count] = malloc(sizeof(struct berval));
            if (!encoded_keys[unique_kvno_count]) {
                ret = ENOMEM;
                goto cleanup;
            }

            encoded_keys[unique_kvno_count]->bv_len = sizeof(krb5_key_data);
            encoded_keys[unique_kvno_count]->bv_val = malloc(encoded_keys[unique_kvno_count]->bv_len);
            if (!encoded_keys[unique_kvno_count]->bv_val) {
                ret = ENOMEM;
                goto cleanup;
            }

            memcpy(encoded_keys[unique_kvno_count]->bv_val, &key_data[i], encoded_keys[unique_kvno_count]->bv_len);
            unique_kvno_count++;
        }
    }

cleanup:
    if (ret != 0) {
        for (i = 0; i < unique_kvno_count; i++) {
            if (encoded_keys[i]) {
                free(encoded_keys[i]->bv_val);
                free(encoded_keys[i]);
            }
        }
        free(encoded_keys);
        encoded_keys = NULL;
    }

    free(key_data);
    return encoded_keys;
}

struct berval** encode_krb5_key_data(krb5_key_data* key_data_in, int n_key_data, krb5_kvno mkvno) {
    if (n_key_data <= 0 || !key_data_in) {
        return NULL;
    }

    int unique_kvno_count = 0;
    krb5_kvno* unique_kvno_list = NULL;

    // Count and collect unique key version numbers
    for (int i = 0; i < n_key_data; ++i) {
        int is_unique = 1;
        for (int j = 0; j < unique_kvno_count; ++j) {
            if (unique_kvno_list[j] == key_data_in[i].key_realm_length) {
                is_unique = 0;
                break;
            }
        }
        if (is_unique) {
            unique_kvno_list = realloc(unique_kvno_list, sizeof(krb5_kvno) * (unique_kvno_count + 1));
            unique_kvno_list[unique_kvno_count++] = key_data_in[i].key_realm_length;
        }
    }

    struct berval** encoded_key_sequences = calloc(unique_kvno_count, sizeof(struct berval*));
    if (!encoded_key_sequences) {
        free(unique_kvno_list);
        return NULL;
    }

    for (int i = 0; i < unique_kvno_count; ++i) {
        int total_length = 0;
        for (int j = 0; j < n_key_data; ++j) {
            if (key_data_in[j].key_realm_length != unique_kvno_list[i])
                continue;
            total_length += key_data_in[j].key_data_length;
        }

        struct berval* encoded = calloc(1, sizeof(struct berval));
        if (!encoded) {
            // Free any allocated berval structures and return on failure
            for (int k = 0; k < i; ++k) {
                free(encoded_key_sequences[k]);
            }
            free(encoded_key_sequences);
            free(unique_kvno_list);
            return NULL;
        }

        encoded->bv_len = total_length;
        encoded->bv_val = malloc(total_length);
        if (!encoded->bv_val) {
            free(encoded);
            for (int k = 0; k < i; ++k) {
                free(encoded_key_sequences[k]);
            }
            free(encoded_key_sequences);
            free(unique_kvno_list);
            return NULL;
        }

        int offset = 0;
        for (int j = 0; j < n_key_data; ++j) {
            if (key_data_in[j].key_realm_length != unique_kvno_list[i])
                continue;
            memcpy(encoded->bv_val + offset, key_data_in[j].key_data, key_data_in[j].key_data_length);
            offset += key_data_in[j].key_data_length;
        }

        encoded_key_sequences[i] = encoded;
    }

    free(unique_kvno_list);
    return encoded_key_sequences;
}

struct berval** encode_krb5_keys(krb5_key_data* key_data_in, int n_key_data, krb5_kvno mkvno) {
    struct berval** encoded_keys = NULL;
    krb5_key_data* key_copy = NULL;
    int i, j, unique_count = 0;
    int* unique_versions = NULL;

    if (n_key_data <= 0 || !key_data_in)
        return NULL;

    key_copy = calloc(n_key_data, sizeof(krb5_key_data));
    if (!key_copy)
        return NULL;

    for (i = 0; i < n_key_data; i++) {
        key_copy[i] = key_data_in[i];
        if (key_copy[i].key_data_ver < 0)
            key_copy[i].key_data_ver = 0;
    }

    unique_versions = calloc(n_key_data, sizeof(int));
    if (!unique_versions) {
        free(key_copy);
        return NULL;
    }

    for (i = 0; i < n_key_data; i++) {
        int is_duplicate = 0;
        for (j = 0; j < unique_count; j++) {
            if (key_copy[i].key_data_ver == unique_versions[j]) {
                is_duplicate = 1;
                break;
            }
        }
        if (!is_duplicate) {
            unique_versions[unique_count++] = key_copy[i].key_data_ver;
        }
    }

    encoded_keys = calloc(unique_count, sizeof(struct berval*));
    if (!encoded_keys) {
        free(key_copy);
        free(unique_versions);
        return NULL;
    }

    for (i = 0; i < unique_count; i++) {
        int version = unique_versions[i];
        struct berval* bval = NULL;
        int count = 0;

        for (j = 0; j < n_key_data; j++) {
            if (key_copy[j].key_data_ver == version) {
                count++;
            }
        }

        bval = calloc(1, sizeof(struct berval));
        if (!bval) {
            while (i-- > 0) free(encoded_keys[i]);
            free(encoded_keys);
            free(key_copy);
            free(unique_versions);
            return NULL;
        }

        bval->bv_len = count;
        bval->bv_val = NULL; /* Encoded data allocation logic assumed here. */
        encoded_keys[i] = bval;
    }

    free(key_copy);
    free(unique_versions);
    return encoded_keys;
}
